package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.math.*;
public class LargeEstimateCheckTest {
 private int round(int n,int unit){return BigDecimal.valueOf(n).divide(BigDecimal.valueOf(unit),0,RoundingMode.HALF_UP).intValueExact()*unit;}
 @Test public void actualFreshLargeSupplyUsesPublicConditionsAndBlankHelp(){for(String id:List.of(EstimateCalculationCheck.ADD,EstimateCalculationCheck.SUB)){CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",id,5);assertTrue(limits.allows(EstimateCalculationCheck.make(id,1000000,1000000,0,1000000)));Generator generator=new Generator(new Random(160));List<String> recent=new ArrayList<>();Set<Integer> units=new HashSet<>();boolean inside=false,outside=false,large=false;for(int i=0;i<300;i++){Question q=generator.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=EstimateCalculationCheck.read(q);assertNotNull(v);int a=v[0],b=v[1],unit=v[3];units.add(unit);large|=a>9999||b>9999;int estimate=id.equals(EstimateCalculationCheck.ADD)?round(a,unit)+round(b,unit):round(a,unit)-round(b,unit);int difference=Math.abs(v[2]-estimate);boolean in=difference<=unit;inside|=in;outside|=!in;assertTrue(Math.abs((id.equals(EstimateCalculationCheck.ADD)?a+b:a-b)-estimate)<=unit);q.answers=new String[]{"poison","poison"};q.expression="poison";Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(""+estimate,in?"0":"1")).correct());assertEquals(0,c.check(q,List.of(),List.of(""+(estimate+1),in?"0":"1")).index);assertEquals(1,c.check(q,List.of(),List.of(""+estimate,in?"1":"0")).index);
 HelpPlan h=HelpPlan.forQuestion(q);assertEquals(17,h.size());assertFalse(h.canTransfer());for(int which=0;which<2;which++){int n=which==0?a:b,base=n/unit*unit,digit=n%unit/(unit/10),off=which*7;String[] entries={""+n,""+unit,""+digit,digit>=5?"raise":"keep",""+base,""+(digit>=5?unit:0),""+round(n,unit)};for(int j=0;j<7;j++)assertTrue(h.step(off+j).accepts(entries[j]));}assertTrue(h.step(14).accepts(""+estimate));assertTrue(h.step(15).accepts(""+difference));assertTrue(h.step(16).accepts(in?"안":"밖"));for(int j=0;j<17;j++)assertFalse(h.step(j).before.matches(".*[0-9].*"));}assertEquals(Set.of(10,100,1000,10000,100000,1000000),units);assertTrue(inside&&outside&&large);}}
 @Test public void smallDomainIsIndexedUniquelyAndExhaustsBeforeOldest(){int max=4;int[] units={10,100};for(String id:List.of(EstimateCalculationCheck.ADD,EstimateCalculationCheck.SUB)){Set<String> independent=new HashSet<>();for(int a=0;a<=max;a++)for(int b=0;b<=max;b++){if(id.equals(EstimateCalculationCheck.SUB)&&a<b)continue;for(int unit:units){int value=id.equals(EstimateCalculationCheck.ADD)?round(a,unit)+round(b,unit):round(a,unit)-round(b,unit);for(int proposed:new int[]{value,value+unit,value+unit+1})independent.add(EstimateCalculationCheck.make(id,a,b,proposed,unit).signature());}}long count=LargeEstimateSupply.count(id,max,units);assertEquals(independent.size(),count);Set<String> indexed=new HashSet<>();for(long i=0;i<count;i++)indexed.add(LargeEstimateSupply.indexed(id,max,units,i).signature());assertEquals(independent,indexed);Map<String,Integer> recent=new LinkedHashMap<>();Random random=new Random(1);for(int i=0;i<count;i++){Question q=LongIndexedQuestionSupply.choose(count,n->LargeEstimateSupply.indexed(id,max,units,n),random,new CurriculumLimits(""),recent);assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),i);}Question oldest=LongIndexedQuestionSupply.choose(count,n->LargeEstimateSupply.indexed(id,max,units,n),random,new CurriculumLimits(""),recent);assertEquals(0,(int)recent.get(oldest.signature()));long large=LargeEstimateSupply.count(id,1000000,new int[]{10,100,1000,10000,100000,1000000});for(long index:new long[]{0,1,large/2,large-2,large-1})assertNotNull(EstimateCalculationCheck.read(LargeEstimateSupply.indexed(id,1000000,new int[]{10,100,1000,10000,100000,1000000},index)));}}
 @Test public void millionBoundariesAndRangeNeverAssertExactEquality(){for(String id:List.of(EstimateCalculationCheck.ADD,EstimateCalculationCheck.SUB))for(int u:new int[]{10,100,1000,10000,100000,1000000})for(int a:new int[]{0,499999,500000,999999,1000000})for(int b:new int[]{0,499999,500000,999999,1000000}){if(id.equals(EstimateCalculationCheck.SUB)&&a<b)continue;int estimate=id.equals(EstimateCalculationCheck.ADD)?round(a,u)+round(b,u):round(a,u)-round(b,u);for(int delta:new int[]{u,u+1}){Question q=EstimateCalculationCheck.make(id,a,b,estimate+delta,u);assertTrue(new Checker().check(q,List.of(),List.of(""+estimate,delta==u?"0":"1")).correct());}}Question q=EstimateCalculationCheck.make(EstimateCalculationCheck.ADD,999999,999999,2000000,1000000);assertNotEquals(1999998,2000000);assertTrue(new Checker().check(q,List.of(),List.of("2000000","0")).correct());q.prompt=q.prompt.replace("999999","1000001");assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("2000000","0")).status);assertEquals(999,GlobalCurriculum.limits("kr-national",EstimateCalculationCheck.ADD,5).wholeMaximum(999));}
}
